  "risk": {
    "level": "medium",
    "touches": [
      "validation"
    ],
    "why": "Mistakes in the lifecycle or destruction order of BlockManager relative to ChainstateManager, or bugs in the relocated prune and block storage flush logic, could lead to crashes or block storage corruption."
  }
}
